WITH unpacked AS (SELECT id, customer_id, coupon_codes, ship_to, SIZE(FILTER(items, item -> item.qty >= 3)) AS bulk_lines, EXISTS(coupon_codes, c -> c LIKE 'W%') AS has_welcome_code, ARRAY_CONTAINS(coupon_codes, 'WELCOME5') AS used_welcome5 FROM carts) SELECT id, customer_id, coupon_codes, bulk_lines, has_welcome_code, used_welcome5, COUNT(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_bulk_lines, SUM(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_bulk_lines, MIN(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_bulk_lines, AVG(bulk_lines) OVER (PARTITION BY customer_id ORDER BY bulk_lines, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS bulk_lines_avg_2_prior FROM unpacked
